-- Daily challenges for 2026-10-12: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-12. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-peace-with-uncertainty', 'Making Peace with Uncertainty', 'For anyone who finds not knowing harder than bad news. Each day is one small practice in acting without every answer, loosening the need for certainty, and noticing how often things work out in ways you could not have planned.', 'Worry', 365, array['Worry', 'Resilience']::text[], 1, '2026-10-12T17:00:00+00:00'::timestamptz),
  ('taking-care-of-future-you', 'Taking Care of Future You', 'For anyone who keeps leaving tomorrow''s problems for tomorrow''s tired self. Each day is one small kindness done now that your future self will thank you for, from a filled water bottle to a booked appointment.', 'Habits', 365, array['Habits', 'Self-Care']::text[], 1, '2026-10-12T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-peace-with-uncertainty', 'taking-care-of-future-you');

